package com.example.activite.web.controller;
import com.example.activite.domain.Maintenance; import com.example.activite.service.IMaintenanceService; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.Parameter; import io.swagger.v3.oas.annotations.responses.*; import io.swagger.v3.oas.annotations.tags.Tag; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/maintenances") @RequiredArgsConstructor @Tag(name="Maintenances",description="Gestion des maintenances") public class MaintenanceController { private final IMaintenanceService maintenanceService;
@GetMapping @Operation(summary="Lister les maintenances") @ApiResponse(responseCode="200",description="Liste retournée") public List<Maintenance> findAll(){return maintenanceService.findAll();}
@GetMapping("/{id}") @Operation(summary="Consulter une maintenance") @ApiResponses({@ApiResponse(responseCode="200",description="Maintenance trouvée"),@ApiResponse(responseCode="404",description="Maintenance introuvable")}) public Maintenance findById(@Parameter(description="Identifiant de la maintenance") @PathVariable Long id){return maintenanceService.findById(id);}
@PostMapping @ResponseStatus(HttpStatus.CREATED) @Operation(summary="Créer une maintenance") @ApiResponses({@ApiResponse(responseCode="201",description="Maintenance créée"),@ApiResponse(responseCode="400",description="Données invalides")}) public Maintenance create(@RequestBody Maintenance m){return maintenanceService.create(m);}
@PutMapping("/{id}") @Operation(summary="Modifier une maintenance") @ApiResponses({@ApiResponse(responseCode="200",description="Maintenance modifiée"),@ApiResponse(responseCode="400",description="Données invalides"),@ApiResponse(responseCode="404",description="Maintenance introuvable")}) public Maintenance update(@PathVariable Long id,@RequestBody Maintenance m){return maintenanceService.update(id,m);}
@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @Operation(summary="Supprimer une maintenance") @ApiResponses({@ApiResponse(responseCode="204",description="Maintenance supprimée"),@ApiResponse(responseCode="404",description="Maintenance introuvable")}) public void deleteById(@PathVariable Long id){maintenanceService.deleteById(id);}}
